local function WeightedPick(arg1, arg2)
	local num1 = 0
	for k1, v1 in ipairs(arg2) do
		local var1 = v1.Weight
		num1 = num1 + var1
	end

	local var2 = arg1:NextNumber() * num1
	for k2, v2 in ipairs(arg2) do
		var2 = var2 - v2.Weight
		if var2 > 0 then
			continue
		end

		return v2
	end

	return arg2[#arg2]
end

local function BuildReward(arg1, arg2)
	local tbl1 = { Id = arg2.Id, Kind = arg2.Kind, Theme = arg2.Theme }
	if arg2.Kind == "Item" then
		tbl1.Item = arg2.Item
		if arg2.Choices then
			tbl1.Amount = arg2.Choices[arg1:NextInteger(1, #arg2.Choices)]
			return tbl1
		end

		if arg2.Step then
			tbl1.Amount = arg1:NextInteger(math.ceil(arg2.Min / arg2.Step), (math.floor(arg2.Max / arg2.Step))) * arg2.Step
			return tbl1
		end

		tbl1.Amount = arg1:NextInteger(arg2.Min, arg2.Max)
		return tbl1
	end

	if arg2.Kind == "Charm" then
		tbl1.Kind = "Item"
		tbl1.Item = arg2.Pool[arg1:NextInteger(1, #arg2.Pool)]
		tbl1.Amount = 1
		return tbl1
	end

	if arg2.Kind == "Boost" then
		tbl1.Potion = arg2.Potion
		tbl1.Minutes = arg1:NextInteger(math.floor(arg2.Min / 5), (math.floor(arg2.Max / 5))) * 5
		return tbl1
	end

	if arg2.Kind == "Rubies" then
		tbl1.Percent = arg1:NextInteger(arg2.Min, arg2.Max)
		return tbl1
	end

	if arg2.Kind == "FruitPack" then
		tbl1.Amount = arg1:NextInteger(arg2.Min, arg2.Max)
	end

	return tbl1
end

