tbl2.RollWeek = function(arg1, arg2)
	local var1 = Random.new(math.clamp(math.floor(tonumber(arg1) or 0), 0, tbl2.MAX_SEED) * 1048576 + math.clamp(math.floor(tonumber(arg2) or 0), 0, 1048576))
	local tbl1 = {}
	local tbl3 = {}
	local tbl4 = {}
	for i1 = 1, 6 do
		local tbl5 = {}
		for k1, v1 in ipairs(tbl6) do
			if tbl3[v1.Id] then
				continue
			end

			if tbl4[v1.Theme] then
				continue
			end

			table.insert(tbl5, v1)
		end

		local var2 = WeightedPick(var1, tbl5)
		tbl3[var2.Id] = true
		tbl4[var2.Theme] = true
		tbl1[i1] = BuildReward(var1, var2)
	end

	tbl1[7] = BuildReward(var1, (WeightedPick(var1, tbl7)))
	return tbl1
end

tbl2.DescribeReward = function(arg1, _)
	if typeof(arg1) ~= "table" then
		return nil
	end

	local tbl1 = { Theme = arg1.Theme }
	if arg1.Kind == "Item" then
