		tbl1.Icon = var4
		tbl1.Hover = "Boost:" .. tostring(arg1.Potion) .. ":" .. var3
		tbl1.Line = tbl1.Name .. " (" .. var3 .. "min)"
		return tbl1
	end

	if arg1.Kind == "Rubies" then
		local var5 = tonumber(arg1.RubiesAmount) or 0
		local var6 = var5 % 1000 == 0 and var5 // 1000 .. "k Rubies" or string.format("%.1f", var5 / 1000):gsub("%.0$", "") .. "k Rubies"
		tbl1.Name = var6
