tbl3.BuildGroups = function()
	local tbl1 = {}
	for k1, v1 in pairs(tbl3.Worlds) do
		for k2, v2 in pairs(v1.Tiers) do
			if not v2.SpawnChance then
				continue
			end

			local num1 = 0
			if num1 >= v2.SpawnChance then
				continue
			end

			local var2 = tbl1[v2.Group]
			if not var2 then
				var2 = { Name = v2.Group, Chance = tbl2[v2.Group] or 0, Worlds = {}, WorldChances = {} }
				tbl1[v2.Group] = var2
			end

			num1 = var2.Worlds[k1]
			if not num1 then
				num1 = {}
				var2.Worlds[k1] = num1
			end

			local tbl4 = { Name = k2, Chance = v2.SpawnChance }
			table.insert(num1, tbl4)
		end
	end

	local str1 = "Rubies"
	local tbl5 = {}
	for k3, v3 in ipairs({ "Coins", str1, "Fruits", "Gems" }) do
		local var3 = tbl1[v3]
		if not var3 then
			continue
		end

		for k4, v4 in pairs(var3.Worlds) do
			local function fn2(arg1, arg2)
				return arg1.Name < arg2.Name
			end

			table.sort(v4, fn2)
		end

		local var4 = var3
		table.insert(tbl5, var4)
	end

	for k5, v5 in ipairs(tbl5) do
		for k6 in pairs(v5.Worlds) do
			v5.WorldChances[k6] = v5.Chance
		end
	end

	local var5 = nil
	for k7, v6 in ipairs(tbl5) do
		if v6.Name ~= "Rubies" then
			continue
		end

		var5 = v6
	end

	if var5 and 0 < var5.Chance then
		for k8 in pairs(var5.Worlds) do
			local var6 = tbl6[k8]
			local var7 = var6
			var7 = var7 and var6.SzansaRubinow
			if typeof(var7) ~= "number" or 0 >= var7 or var7 == 1 then
				continue
			end

			local num2 = 0
			for k9, v7 in ipairs(tbl5) do
				if v7.Name == "Rubies" then
					continue
				end

				if not v7.Worlds[k8] then
					continue
				end

				num2 = num2 + v7.Chance
			end

			if 0 >= num2 then
				continue
			end

			local var8 = var5.Chance
			local var9 = var5.Chance / (num2 + var8) * var7
			if 0 >= var9 or var9 >= 1 then
				continue
			end

			var8 = 1 - var9
			var5.WorldChances[k8] = var9 * num2 / var8
		end
	end

	return tbl5
end

