local function Short(arg1)
	arg1 = math.floor(tonumber(arg1) or 0)
	local var2 = math.abs(arg1)
	local var3 = arg1 < 0
	if var2 < 1000 then
		return (tostring(arg1))
	end

	for k1, v1 in ipairs(tbl2) do
		local var4 = v1[1]
		if var4 > var2 then
			continue
		end

		local var5 = math.floor(var2 * 10 / var4)
		local var6 = v1[2]
		local var7 = nil
		var7 = if var5 % 10 == 0 then tostring(var5 // 10) else string.format("%d.%d", var5 // 10, var5 % 10)
		return (if var3 then "-" else "") .. var7 .. var6
	end

	return (tostring(arg1))
end

