	{ min = 11, max = 80, multiplier = 1.0236 },
	{ min = 81, max = 100, multiplier = 1.0256 },
}

local tbl2 = {}
str1 = function(arg1)
	for k1, v1 in ipairs(tbl1) do
		if v1.min > arg1 then
			continue
		end

		if arg1 > v1.max then
			continue
		end

		return v1.multiplier
	end
end

local var2 = table.create(100)
local num1 = 50
for i1 = 1, 100 do
	if 1 < i1 then
		num1 = num1 * str1(i1)
	end

	var2[i1] = num1
end

tbl2.GetLevel = function(arg1)
