		if num1 >= 100 then
			break
		end

		local var1
		if num1 < 1 then
			var1 = var2[1]
		else
			var1 = var2[num1]
			var1 = var1 or var2[100]
		end

		if num2 + var1 > arg1 then
			break
		end

		num1 = num1 + 1
		num2 = num2 + var1
		continue
	end

	return num1, num2
end

tbl2.GetProgress = function(arg1)
	local var4, var5 = tbl2.GetLevel(arg1)
	local var6
	if var4 < 1 then
		var6 = var2[1]
	else
		var6 = var2[var4]
		var6 = var6 or var2[100]
	end

	return (arg1 - var5) / var6
end

